#include <bits/stdc++.h>
using namespace std;
int main(){int n; if(!(cin>>n)) return 0; map<string, multiset<string>> g; string w;
 for(int i=0;i<n;i++){cin>>w; string k=w; sort(k.begin(),k.end()); g[k].insert(w);}
 vector<pair<int,string>> order; for(auto&[k,s]:g) order.push_back({-(int)s.size(), *s.begin()});
 sort(order.begin(), order.end());
 cout<<g.size()<<"\n";
 // need per-group lines in requested order: rebuild mapping
 map<string, vector<string>> bykey; for(auto&[k,s]:g){for(const auto&x:s) bykey[k].push_back(x);}
 for(auto&[sz,fst]:order){ string k=fst; sort(k.begin(),k.end()); auto&v=bykey[k];
 for(size_t i=0;i<v.size();i++) cout<<v[i]<<" \n"[i+1==v.size()]; }
 return 0;}
